package com.dshgo.shellpol;
import android.os.Build;import android.os.Process;import java.io.*;import java.util.zip.*;
/** Loads the library for this module's class loader without relying on LSPosed search paths. */
public final class NativeLibrary{private static boolean loaded;private NativeLibrary(){}public static synchronized String load(String apk,File cache,String extractedDir)throws IOException{if(loaded)return "already-loaded";String[] abis=Process.is64Bit()?Build.SUPPORTED_64_BIT_ABIS:Build.SUPPORTED_32_BIT_ABIS;StringBuilder failures=new StringBuilder();for(String abi:abis){try{System.load(apk+"!/lib/"+abi+"/libdexkit.so");loaded=true;return "apk-direct:"+abi;}catch(UnsatisfiedLinkError e){failures.append(e).append('\n');}}if(!cache.isDirectory()&&!cache.mkdirs())throw new IOException("Cannot create native cache: "+cache);try(ZipFile zip=new ZipFile(apk)){for(String abi:abis){ZipEntry entry=zip.getEntry("lib/"+abi+"/libdexkit.so");if(entry==null)continue;File target=new File(cache,"dexkit-"+abi+"-"+Long.toHexString(entry.getCrc())+"-"+entry.getSize()+".so");File temp=File.createTempFile("dexkit-",".tmp",cache);try{CRC32 crc=new CRC32();long size=0;try(InputStream in=zip.getInputStream(entry);FileOutputStream out=new FileOutputStream(temp)){byte[] buf=new byte[32768];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);crc.update(buf,0,n);size+=n;}out.getFD().sync();}if(crc.getValue()!=entry.getCrc()||size!=entry.getSize())throw new IOException("Native library CRC/size mismatch");if(!temp.setReadable(true,true)||!temp.setExecutable(true,true))throw new IOException("Native file permissions failed");if(!temp.renameTo(target))throw new IOException("Cannot publish native library");System.load(target.getAbsolutePath());loaded=true;return "verified-extraction:"+abi;}catch(UnsatisfiedLinkError e){failures.append(e).append('\n');}finally{if(temp.exists())temp.delete();}}}throw new UnsatisfiedLinkError("No compatible DexKit library loaded: "+failures);}}
